hl.bind("SUPER + ALT + Right", function() local w = hl.get_active_window(); if w == nil then return end; if w.floating or hl.get_active_workspace().tiled_layout ~= "scrolling" then hl.dispatch(hl.dsp.window.resize({ x = 50, y = 0, relative = true })) else hl.dispatch(hl.dsp.layout("colresize +0.1")) end end)
hl.bind("SUPER + ALT + l", function() local w = hl.get_active_window(); if w == nil then return end; if w.floating or hl.get_active_workspace().tiled_layout ~= "scrolling" then hl.dispatch(hl.dsp.window.resize({ x = 50, y = 0, relative = true })) else hl.dispatch(hl.dsp.layout("colresize +0.1")) end end)
hl.bind("SUPER + ALT + Left", function() local w = hl.get_active_window(); if w == nil then return end; if w.floating or hl.get_active_workspace().tiled_layout ~= "scrolling" then hl.dispatch(hl.dsp.window.resize({ x = -50, y = 0, relative = true })) else hl.dispatch(hl.dsp.layout("colresize -0.1")) end end)
hl.bind("SUPER + ALT + h", function() local w = hl.get_active_window(); if w == nil then return end; if w.floating or hl.get_active_workspace().tiled_layout ~= "scrolling" then hl.dispatch(hl.dsp.window.resize({ x = -50, y = 0, relative = true })) else hl.dispatch(hl.dsp.layout("colresize -0.1")) end end)
hl.bind("SUPER + ALT + Down", function()
	local w = hl.get_active_window()
	if w == nil then return end
	local delta = 50
	if not w.floating and hl.get_active_workspace().tiled_layout == "scrolling" then
		local below = false
		for _, o in ipairs(hl.get_workspace_windows(hl.get_active_workspace())) do
			if o ~= w and not o.floating then
				local overlap = math.min(w.at.x + w.size.x, o.at.x + o.size.x) - math.max(w.at.x, o.at.x)
				if overlap > 0 and o.at.y >= w.at.y + w.size.y - 10 then
					below = true
					break
				end
			end
		end
		if not below then
			delta = -50
		end
	end
	hl.dispatch(hl.dsp.window.resize({ x = 0, y = delta, relative = true }))
end)
