-- Caelestia Shell
hl.on("hyprland.start", function()
    hl.exec_cmd("quickshell -n -d -c violet-login-transition")
    hl.exec_cmd("caelestia shell -d")
    hl.exec_cmd("quickshell -n -d -c ambxst-clock")
    hl.exec_cmd("wl-paste --watch cliphist store")
end)

